export function translate(language, key) { return messages[language]?.[key] ?? messages.en[key] ?? key; }

export function initLanguage() {
  let language = navigator.language.toLowerCase().startsWith('ko') ? 'ko' : 'en';
  try { const stored = localStorage.getItem('record-review-mobile-language'); if (stored === 'ko' || stored === 'en') language = stored; } catch {}
  const listeners = new Set();
  function render(persist = false) {
    document.documentElement.lang = language;
    document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = translate(language, el.dataset.i18n); });
    document.querySelectorAll('[data-i18n-aria]').forEach(el => { el.setAttribute('aria-label', translate(language, el.dataset.i18nAria)); });
    document.querySelectorAll('[data-i18n-title]').forEach(el => { el.setAttribute('title', translate(language, el.dataset.i18nTitle)); });
    document.querySelectorAll('[data-language-toggle]').forEach(el => {
      el.textContent = language === 'ko' ? 'KOR' : 'ENG';
      el.setAttribute('aria-label', translate(language, 'language.switch'));
      el.title = translate(language, 'language.switch');
    });
    if (persist) try { localStorage.setItem('record-review-mobile-language', language); } catch {}
    listeners.forEach(fn => fn());
  }
  document.querySelectorAll('[data-language-toggle]').forEach(el => el.addEventListener('click', () => { language = language === 'ko' ? 'en' : 'ko'; render(true); }));
  render();
  return { t: key => translate(language, key), get language() { return language; }, onChange(fn) { listeners.add(fn); } };
}
